var TC = window.__TC || (window.__TC = {});

// One task: an 8,000-token prefix, twelve steps, 1,500 tokens added per
// step. Every figure on screen is derived from these three numbers.
TC.PREFIX = 8000;
TC.GROW = 1500;
TC.STEPS = 12;
TC.tokens = [];
for (var i = 0; i < TC.STEPS; i++) TC.tokens.push(TC.PREFIX + i * TC.GROW);
TC.MAX = TC.tokens[TC.STEPS - 1];

TC.scene = function(id, whip){
  MSD.cls('.tc-sc', 'on', false);
  MSD.cls('#tc-sc-' + id, 'on', true);
  MSD.cls('#tc-sc-' + id, 'whip', false);
  if(whip) MSD.after(20, function(){ MSD.cls('#tc-sc-' + id, 'whip', true); MSD.sfx.swipe(); });
};

TC.header = function(app, amount, tone, health){
  MSD.q('#tc-app').textContent = app;
  MSD.q('#tc-rt-n').textContent = amount;
  MSD.cls('#tc-rt', 'bad', tone === 'bad');
  MSD.cls('#tc-rt', 'ok', tone === 'ok');
  MSD.cls('#tc-health', 'bad', tone === 'bad');
  MSD.cls('#tc-health', 'warn', tone === 'warn');
  MSD.q('#tc-health-t').textContent = health;
};

/** Paints one bar row. Widths are percentages of the tallest bar. */
TC.bar = function(index, cold, read, write){
  var row = MSD.qa('#tc-rows .tc-row')[index];
  if(!row) return;
  var pct = function(v){ return (v / TC.MAX * 100) + '%'; };
  row.querySelector('.c').style.width = pct(cold);
  row.querySelector('.r').style.width = pct(read);
  row.querySelector('.w').style.width = pct(write);
};

/** Full-price view: the whole conversation billed at the input rate. */
TC.cold = function(upTo){
  TC.tokens.forEach(function(t, i){
    TC.bar(i, i < upTo ? t : 0, 0, 0);
  });
};

/** Cached view: same bar length, repriced. Step one writes the prefix;
    every later step reads what the last one left and writes the delta. */
TC.cached = function(){
  TC.tokens.forEach(function(t, i){
    if(i === 0) TC.bar(i, 0, 0, TC.PREFIX);
    else TC.bar(i, 0, t - TC.GROW, TC.GROW);
  });
};

TC.keys = function(cold, read, write){
  MSD.cls('#tc-key-c', 'on', !!cold);
  MSD.cls('#tc-key-r', 'on', !!read);
  MSD.cls('#tc-key-w', 'on', !!write);
};

TC.sum = function(label, text, amount, tone){
  MSD.cls('#tc-sum', 'bad', tone === 'bad');
  MSD.cls('#tc-sum', 'good', tone === 'good');
  MSD.q('#tc-sum-l').textContent = label;
  MSD.q('#tc-sum-t').textContent = text;
  MSD.q('#tc-sum-n').textContent = amount;
};

TC.note = function(id, label, text, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.cls(id, 'good', tone === 'good');
  MSD.q(id + '-l').textContent = label;
  MSD.q(id + '-t').textContent = text;
};

TC.money = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    var v = Math.round(from + (to - from) * p);
    el.textContent = '$' + v.toLocaleString('en-US');
    if(p >= 1) clearInterval(id);
  });
};

TC.scene('bill');
TC.header('triage-agent · billing', '$0', '', 'healthy');
TC.cold(0);
TC.keys(false, false, false);
MSD.cls('#tc-twist', 'on', false);
MSD.cls('#tc-line-bad', 'hot', false);
TC.note('#tc-note', 'NO INCIDENT', 'No outage, no bug, no failed run. The agent did exactly what it was built to do.', '');
MSD.qa('#tc-daily i').forEach(function(el){ el.style.height = '8%'; });

// The invoice number climbs on the hook rather than simply appearing.
MSD.q('#tc-inv-n').textContent = '$0';
MSD.after(300, function(){
  MSD.qa('#tc-daily i').forEach(function(el, i){
    MSD.after(i * 60, function(){
      el.style.height = (10 + i * 6.2) + '%';
    });
  });
  MSD.sfx.riser(1400);
});
MSD.after(500, function(){
  TC.money('#tc-inv-n', 0, 4260, 1700);
  TC.money('#tc-rt-n', 0, 4260, 1700);
});
MSD.after(2350, function(){
  TC.header('triage-agent · billing', '$4,260', 'bad', 'over budget');
  MSD.punch('#tc-inv', 4);
  MSD.sfx.thud();
});

var TC = window.__TC;

